export function VoiceControls({
  status,
  muted,
  onMute,
  onStop,
  stopLabel,
}: {
  status: VoiceStatus;
  muted: boolean;
  onMute: (muted: boolean) => void;
  onStop: () => void;
  stopLabel: string;
}) {
  const label = muted && status === "listening" ? "Muted" : LABELS[status];
