        <span className="truncate font-serif text-[17px]">{label}</span>
      </div>
      <button
        className="btn-quiet shrink-0 px-4 py-2.5"
        onClick={() => onMute(!muted)}
        disabled={status === "connecting"}
        aria-pressed={muted}
